{
 "app_name": "venmo",
 "api_name": "approve_payment_request",
 "path": "/payment_requests/{payment_request_id}/approve",
 "method": "POST",
 "description": "Approve a payment request.",
 "parameters": [
  {
   "name": "payment_request_id",
   "type": "integer",
   "required": true,
   "description": "ID of the payment request to approve.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "payment_card_id",
   "type": "integer",
   "required": false,
   "description": "ID of the payment card to use for approving the payment request. If not passed, Venmo balance will be used.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "venmo",
 "api_name": "show_venmo_balance",
 "path": "/balance",
 "method": "GET",
 "description": "Show your Venmo balance.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "venmo_balance": 0.0
  },
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "venmo",
 "api_name": "show_payment_cards",
 "path": "/payment_cards",
 "method": "GET",
 "description": "Get a list of users payment cards.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "payment_card_id": 1,
    "card_name": "string",
    "owner_name": "string",
    "card_number": 1000000000000000.0,
    "expiry_year": 1,
    "expiry_month": 1.0,
    "cvv_number": 100.0
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}
